18	// ─── Thread-local stream override for Green Context SM partitioning ────────
19	
20	thread_local! {
21	    static STREAM_OVERRIDE: Cell<Option<CUstream>> = const { Cell::new(None) };
22	    static PREFILL_STREAM_OVERRIDE: Cell<bool> = const { Cell::new(false) };
23	}
24	
25	/// Scoped stream override for [`active_cu_stream`]; drop restores the previous value.
26	pub struct StreamOverrideGuard {
27	    previous: Option<CUstream>,
28	    previous_prefill: bool,
29	}
30	
31	impl StreamOverrideGuard {
32	    /// # Safety
33	    /// The stream must be valid for the guard's lifetime and belong to the
34	    /// same CUDA device as the `DeviceContext`.
35	    pub unsafe fn activate(stream: CUstream) -> Self {
36	        Self::activate_inner(stream, false)
37	    }
38	
39	    /// # Safety
40	    /// The stream must be valid for the guard's lifetime and belong to the
41	    /// same CUDA device as the `DeviceContext`.
42	    pub unsafe fn activate_prefill(stream: CUstream) -> Self {
43	        Self::activate_inner(stream, true)
44	    }
45	
46	    fn activate_inner(stream: CUstream, prefill: bool) -> Self {
47	        let previous = STREAM_OVERRIDE.with(|c| c.replace(Some(stream)));
48	        let previous_prefill = PREFILL_STREAM_OVERRIDE.with(|c| c.replace(prefill));
49	        Self {
50	            previous,
51	            previous_prefill,
52	        }
53	    }
54	}
55	
